    "purpose": "Bu dersin amacı çimlenme ve çimlenmeye etki eden ekolojik faktörleri öğretmek ve dolayısıyla öğrencinin sentez yapabilme gücünü geliştirmektir.",
    "content": "Çimlenme ve çimlenmeyi kontrol eden faktörlerin genel değerlendirilmesiKlimatik faktörlerHidrik faktörlerToprak faktörleriBiotik faktörlerTüm bu faktörlerin çimlenmeye etkisi",
    "methods": "Yüzyüze teorik anlatım.",
    "resources": "Kaynaklar: 1.Bewley, J.D. and Black, M. 1994. Seeds (Physiology of Development and Germination). Plenum Press, New York. 2.Fenner, M. and Thompson, K. 2003. The Ecology of Seeds. Cambridge University Press, Cambridge.; Ders Notları: 1.Bewley, J.D. and Black, M. 1994. Seeds (Physiology of Development and Germination). Plenum Press, New York.2.Fenner, M. and Thompson, K. 2003. The Ecology of Seeds. Cambridge University Press, Cambridge.",
