    "purpose": "DNA replikasyonu, transkripsiyon, translasyon gibi temel moleküler biyoloji süreçlerinin yanı sıra, bu süreçlerdeki düzenleme mekanizmalarının detaylı bir şekilde öğrenilmesi.Genetik materyalin ve genetik bilgilerin hücresel ve organizmal seviyede nasıl kontrol edildiğini anlamak.",
    "content": "Bu ders sadece yüz yüze eğitim şeklinde yürütülmektedir.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, biyolojik veri yorumlama, yöntem karşılaştırması ve akademik tartışma.",
    "resources": "Kaynaklar: Öğretim elemanı tarafından sağlanacak ders malzemeleri.; Ders Notları: Applied Molecular Genetics, Roger L. MiesfeldMolecular Biotechnology Bernard R. Glick, Cheryl L. PattenJohn Wiley & Sons, 2022",
