    "content": "Mikroorganizma genetiği; mikrobiyal yapı ve çeşitlilik, gelişme ve metabolizma, konak-mikroorganizma etkileşimi, kontrol ve direnç mekanizmaları, örnekleme ve kültür yaklaşımları, moleküler tanımlama, veri yorumlama, biyogüvenlik ve etik boyutlarıyla ele alınır.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, biyolojik veri yorumlama, yöntem karşılaştırması ve akademik tartışma.",
