    "instructor": "Prof. Dr. Fuat BOZOK yok fbozok@osmaniye.edu.tr",
    "purpose": "Mantarların genel özelliklerinin anlatılması. Multidisipliner alanlarda kullanılan önemli mantar türlerinin önemi. Farklı mantar türlerinin sağlık açısından önemi ve mantar türlerinin meydana getirdikleri hastalıkların öğrenilmesi.",
    "content": "Mantarların hayat devreleri, Parazit mantarların konakçı özellikleri, mantarların kullanıldıkları alanlar, endüstride kullanılan mantarlar, yenebilen ve zehirli mantarlar.",
    "methods": "Yüzyüze",
    "resources": "Kaynaklar: yok; Ders Notları: Bitkisel üretimde hastalıklar : canlı hastalık etmenleri, bakteriler, mantarlar, nematodlar, virüsler : ilaç tavsiyeleri, cansız etmenler / Himmet KaygısızDerinin mantar hastalıkları / Nizamettin Erbakan",
