      "Tanenler ve musilajlar",
      "Organik asitler",
      "Bitkisel mumlar",
      "Türkiye'de doğal ürünler hakkında yasal düzenlemeler ve mevzuatlar.",
      "Sekonder metabolitlerin ekstraksiyon yöntemleri",
      "Doğal ürünlerin biyolojik aktiviteleri: kapsam, temel kavramlar ve terminoloji",
