    "purpose": "Bu dersin temel amacı, öğrencilere evrimsel biyoloji alanında moleküler yöntemleri ve analizleri kullanarak türler arasındaki ilişkileri ve evrimsel süreçleri anlamalarını sağlamaktır. Öğrencilerin evrimsel teorinin temel prensiplerini kavramaları ve bu prensipleri moleküler düzeyde uygulayarak biyolojik çeşitliliğin kökeni ve evrimin mekanizmaları hakkında derin bir anlayışa sahip olmaları hedeflenmektedir.",
    "content": "Bu ders, temel evrimsel ilkeleri kavratmak için evrimin tanımı, doğal seçilim, genetik çeşitlilik ve adaptasyon gibi konularla başlar ve ardından moleküler evrim ve filogenetik analizleri, popülasyon genetiği ve evrimsel süreçleri, moleküler adaptasyonu ve konvergent evrimi, moleküler coğrafi ve ekolojik evrimi, son olarak da tıp, biyoteknoloji, mikrobiyoloji ve ekoloji gibi alanlardaki moleküler evrim uygulamalarını kapsayacak şekilde ilerler.",
    "methods": "Kuramsal anlatım, bilimsel kaynak incelemesi, biyolojik veri yorumlama, yöntem karşılaştırması ve akademik tartışma.",
    "resources": "Kaynaklar: Evolutionary Analysis - Scott Freeman ve Jon C. Herron",
    "sdgs": [
      "4",
      "9",
      "15"
    ],
    "outcomes": [
      "Evrimsel analiz kapsamındaki ileri biyolojik kavramları analiz eder.",
      "ileri biyoloji araştırmaları alanındaki bilimsel yaklaşımları karşılaştırır.",
      "Evrimsel analiz için uygun araştırma veya inceleme yöntemini uygular.",
      "Evrimsel analiz verilerini bilimsel ölçütlerle değerlendirir.",
      "Evrimsel analiz bulgularını etik ve biyolojik bağlamda yorumlar."
    ],
    "weeklyTopics": [
      "Moleküler evrimin tanımı ve temel prensipleri",
      "Genetik varyasyonun moleküler temelleri",
      "DNA dizilerinin karşılaştırılması",
      "Ortak ataların belirlenmesi ve moleküler filogenetik yöntemleri",
      "Popülasyon genetiğinin temel prensipleri",
      "Genetik sürüklenme, doğal seçilim ve gen akışının moleküler düzeyde etkileri",
      "Moleküler adaptasyonun tanımı ve örnekleri",
      "Doğal seçilimin moleküler temelleri",
      "Gen ifadesinin evrimsel değişimi ve adaptasyon üzerindeki etkileri",
      "Coğrafi izolasyonun moleküler mekanizmaları",
      "Ekolojik baskıların moleküler evrim üzerindeki etkileri",
      "Moleküler evrimin biyoteknolojideki uygulamaları",
      "Antibiyotik direnci ve mikrobiyal evrimin moleküler mekanizmaları",
      "Moleküler Evrim ve Gelecek Perspektifler",
      "Evrimsel analiz: kapsam, temel kavramlar ve terminoloji"
    ],
