    "purpose": "Bu dersin amacı çimlenme ve çimlenmeye etki eden ekolojik faktörleri öğretmek ve dolayısıyla öğrencinin sentez yapabilme gücünü geliştirmektir.",
    "content": "Çimlenme ve çimlenmeyi kontrol eden faktörlerin genel değerlendirilmesiKlimatik faktörlerHidrik faktörlerToprak faktörleriBiotik faktörlerTüm bu faktörlerin çimlenmeye etkisi",
