    "content": "Makromoleküllerde yapısal olarak problemlerin çözümü, ph ve tampon çözeltiler, asit-baz denge soruları, enzimler, proteinler, karbonhidratlar ve lipidler ile ilgili hesaplamalar.",
    "methods": "Instruction, question-answers",
    "resources": "Kaynaklar: Biyokimyasal hesaplamalar, IRWIN H.SEGEL palme kitabevi; Ders Notları: Öğretim görevlisi notları; Dökümanlar: Lehninger Principles of Biochemistry; Ödevler: 1; Sınavlar: 2",
