      "Örnekleme yöntemleri ve örneklem büyüklüğünün belirlenmesi",
      "Biyolojik araştırmalarda kullanılan temel deneysel teknikler",
      "İleri düzey biyolojik analiz teknikleri (moleküler, hücresel, mikrobiyolojik)",
