    "level": "Tezli Yüksek Lisans",
    "teachingMode": "Yüz Yüze",
    "theory": 3,
    "practice": 0,
    "credit": 3,
    "ects": 6,
    "prerequisites": "Yok",
    "instructor": "Dr. Öğr. Üyesi Emre Cem ERASLAN https://www.osmaniye.edu.tr/mdbf/biyoloji emrecemeraslan@osmaniye.edu.tr",
    "purpose": "Dersin amacı, yüksek lisans öğrencilerine gıdalarda bulunan doğal antioksidan bileşiklerin kimyasal yapısını, biyolojik etkilerini ve bu bileşiklerin insan sağlığı açısından önemini öğretmektir. Öğrencilerin antioksidan aktivite analiz yöntemlerini teorik ve uygulamalı düzeyde öğrenmeleri hedeflenmektedir.",
    "content": "Gıdalarda Antioksidan Aktivite dersinde; serbest radikal oluşumu, antioksidan kavramı, gıdalarda bulunan başlıca doğal antioksidanlar (fenolik bileşikler, karotenoidler, vitaminler vb.), bu bileşiklerin sağlık üzerine etkileri, gıda işleme ve depolama sırasında antioksidan davranışı, gıdalarda antioksidan aktiviteyi belirlemeye yönelik analitik yöntemler ve fonksiyonel gıdalar çerçevesinde değerlendirmeler ele alınacaktır.",
    "methods": "Ders, teorik anlatımlar, bilimsel makale incelemeleri ve güncel araştırma örnekleriyle yürütülür. Öğrenciler, gıdalarda bulunan doğal antioksidan bileşiklerin yapısını, etki mekanizmalarını ve oksidatif süreçlerin gıda kalitesi üzerindeki etkilerini öğrenirler. Ayrıca, antioksidan aktivitenin değerlendirilmesinde kullanılan temel prensipler ve güncel yaklaşımlar tartışılır.",
    "resources": "Kaynaklar: Shahidi, F. (2015). Antioxidants: Principles and applications. In Handbook of antioxidants for food preservation (pp. 1-14). Woodhead Publishing.; Ders Notları: Shahidi, F. (2015). Antioxidants: Principles and applications. In Handbook of antioxidants for food preservation (pp. 1-14). Woodhead Publishing.Pokorny, J., Yanishlieva, N., & Gordon, M. (Eds.). (2001). Antioxidants in Food: Practical Applications. CRC Press.Carlsen, M. H. et al. (2010). The total antioxidant content of more than 3100 foods, beverages, spices, herbs and supplements used worldwide Nutrition Journal",
    "sdgs": [
      "3",
      "4",
      "9"
    ],
    "outcomes": [
      "Gıdalarda antioksidan aktiviteler kapsamındaki ileri biyolojik kavramları analiz eder.",
      "fizyoloji, biyokimya ve toksikoloji alanındaki bilimsel yaklaşımları karşılaştırır.",
      "Gıdalarda antioksidan aktiviteler için uygun araştırma veya inceleme yöntemini uygular.",
      "Gıdalarda antioksidan aktiviteler verilerini bilimsel ölçütlerle değerlendirir.",
      "Gıdalarda antioksidan aktiviteler bulgularını etik ve biyolojik bağlamda yorumlar."
    ],
    "weeklyTopics": [
      "Temel Kavramlarla Antioksidanlar",
      "Serbest Radikallerin Oluşumu ve Biyolojik Etkileri",
      "Endojen Antioksidan Sistemler",
      "Eksojen Antioksidan Sistemler",
      "Fenolik Bileşikler ve Antioksidan Özellikleri",
      "Karotenoidler ve Antioksidan Fonksiyonları",
      "C, E Vitamini ve Diğer Vitaminlerin Antioksidan Rolü",
      "Gıda Matrisinde Antioksidanların Davranışı ve Stabilitesi",
      "Antioksidan Aktivitenin Ölçüm Yöntemleri",
      "Bitkisel Kaynaklı Antioksidanlar",
      "Hayvansal Kaynaklı Bileşiklerde Antioksidan Aktivite",
      "Gıda İşleme ve Depolamanın Antioksidanlara Etkisi",
      "Fonksiyonel Gıdalarda Antioksidan Kullanımı ve Etik Etiketleme",
      "Antioksidan Nanoteknolojisi ve Nano-Taşıyıcı Sistemlerde Antioksidan Stabilitesi",
      "Gıdalarda antioksidan aktiviteler: kapsam, temel kavramlar ve terminoloji"
    ],
